Out_PermOK := ((Inp_PermOK OR Inp_Bypass) AND Inp_NBPermOK);
Out_IntlkOK := ((Inp_IntlkOK OR Inp_Bypass) AND Inp_NBIntlkOK);
IF (Inp_Source = 1) THEN
    IF Inp_PSetOverride THEN
        Out_RefSpeed := Inp_MPSet;
    ELSE
        Out_RefSpeed := Inp_PSpeed;
    END_IF;
    RunFwd := (((Inp_PRunFwd AND (Out_PermOK OR RunFwd)) AND Out_IntlkOK) AND NOT (Inp_PStop));
    RunRev := (((Inp_PRunRev AND (Out_PermOK OR RunRev)) AND Out_IntlkOK) AND NOT (Inp_PStop));
ELSIF (Inp_Source = 2) THEN
    Out_RefSpeed := Inp_OSpeed;
    RunFwd := (((RunFwd OR (((Inp_ORunFwd AND Inp_RunFwdAvail) AND Out_PermOK) AND NOT (Inp_ORunRev))) AND Out_IntlkOK) AND NOT (Inp_OStop));
    RunRev := (((RunRev OR (((Inp_ORunRev AND Inp_RunRevAvail) AND Out_PermOK) AND NOT (Inp_ORunFwd))) AND Out_IntlkOK) AND NOT (Inp_OStop));
ELSIF (Inp_Source = 3) THEN
    Out_RefSpeed := Inp_XSpeed;
    RunFwd := (((RunFwd OR (((Inp_XRunFwd AND Inp_RunFwdAvail) AND Out_PermOK) AND NOT (Inp_XRunRev))) AND Out_IntlkOK) AND NOT (Inp_XStop));
    RunRev := (((RunRev OR (((Inp_XRunRev AND Inp_RunRevAvail) AND Out_PermOK) AND NOT (Inp_XRunFwd))) AND Out_IntlkOK) AND NOT (Inp_XStop));
ELSIF (Inp_Source = 4) THEN
    Out_RefSpeed := Inp_OvSpeed;
    IF ((Inp_OvCmd = 1) OR NOT (Out_IntlkOK)) THEN
        RunFwd := FALSE;
        RunRev := FALSE;
    ELSIF ((Inp_OvCmd = 2) AND Out_PermOK) THEN
        RunRev := FALSE;
        RunFwd := TRUE;
    ELSIF ((Inp_OvCmd = 3) AND Out_PermOK) THEN
        RunFwd := FALSE;
        RunRev := TRUE;
    END_IF;
ELSIF (Inp_Source = 5) THEN
    Out_RefSpeed := Inp_MSpeed;
    RunFwd := (((RunFwd OR (((Inp_MRunFwd AND Inp_RunFwdAvail) AND Out_PermOK) AND NOT (Inp_MRunRev))) AND Out_IntlkOK) AND NOT (Inp_MStop));
    RunRev := (((RunRev OR (((Inp_MRunRev AND Inp_RunRevAvail) AND Out_PermOK) AND NOT (Inp_MRunFwd))) AND Out_IntlkOK) AND NOT (Inp_MStop));
ELSE
    Out_RefSpeed := 0.0;
    RunFwd := FALSE;
    RunRev := FALSE;
END_IF;
Out_JogFwd := (((Inp_JogFwdAvail AND Out_PermOK) AND (((((Inp_Source = 2) AND Inp_OJogFwd) AND NOT (Inp_OJogRev)) OR (((Inp_Source = 3) AND Inp_XJogFwd) AND NOT (Inp_XJogRev))) OR (((Inp_Source = 5) AND Inp_MJogFwd) AND NOT (Inp_MJogRev)))) OR (((Inp_Source = 1) AND Inp_PJogFwd) AND NOT (Inp_PJogRev)));
Out_JogRev := (((Inp_JogRevAvail AND Out_PermOK) AND (((((Inp_Source = 2) AND Inp_OJogRev) AND NOT (Inp_OJogFwd)) OR (((Inp_Source = 3) AND Inp_XJogRev) AND NOT (Inp_XJogFwd))) OR (((Inp_Source = 5) AND Inp_MJogRev) AND NOT (Inp_MJogFwd)))) OR (((Inp_Source = 1) AND Inp_PJogRev) AND NOT (Inp_PJogFwd)));
IF (RunFwd OR RunRev) THEN
    StartElapsedMs := (StartElapsedMs + Inp_ElapsedMs);
    IF (StartElapsedMs >= Inp_StartDelayMs) THEN
        StartElapsedMs := Inp_StartDelayMs;
        TimerDone := TRUE;
    ELSE
        TimerDone := FALSE;
    END_IF;
ELSE
    StartElapsedMs := 0;
    TimerDone := FALSE;
END_IF;
Out_Starting := ((RunFwd OR RunRev) AND NOT (TimerDone));
StopCmd := ((Inp_Active AND Inp_ENetLogicCtrl) AND NOT (((((Inp_KeypadCtrlSts OR RunFwd) OR RunRev) OR Out_JogFwd) OR Out_JogRev)));
StartCmd := (((Inp_Ready AND TimerDone) AND NOT (StopCmd)) AND (((RunFwd OR RunRev) OR Out_JogFwd) OR Out_JogRev));
JogCmd := ((Inp_Ready AND NOT (((StopCmd OR RunFwd) OR RunRev))) AND (Out_JogFwd OR Out_JogRev));
ResetCmd := (((Inp_PReset OR Inp_OReset) OR Inp_XReset) OR Inp_MReset);
Out_LogicCommand := 0;
IF StopCmd THEN
    Out_LogicCommand := (Out_LogicCommand + 1);
END_IF;
IF StartCmd THEN
    Out_LogicCommand := (Out_LogicCommand + 2);
END_IF;
IF JogCmd THEN
    Out_LogicCommand := (Out_LogicCommand + 4);
END_IF;
IF ResetCmd THEN
    Out_LogicCommand := (Out_LogicCommand + 8);
END_IF;
IF (RunFwd OR Out_JogFwd) THEN
    Out_LogicCommand := (Out_LogicCommand + 16);
END_IF;
IF (RunRev OR Out_JogRev) THEN
    Out_LogicCommand := (Out_LogicCommand + 32);
END_IF;
IF Inp_KeypadCtrlCmd THEN
    Out_LogicCommand := (Out_LogicCommand + 64);
END_IF;
IF (Out_JogFwd OR Out_JogRev) THEN
    SpeedRef := Inp_JogSpeed;
ELSE
    SpeedRef := Out_RefSpeed;
END_IF;
IF (SpeedRef < 0.0) THEN
    SpeedRef := 0.0;
ELSIF (SpeedRef > Inp_MaxSpeed) THEN
    SpeedRef := Inp_MaxSpeed;
END_IF;
Out_SpeedCommand := REAL_TO_INT((SpeedRef * 100.0));
Out_RunFwd := RunFwd;
Out_RunRev := RunRev;
Out_Stopping := (Inp_Active AND NOT ((((RunFwd OR RunRev) OR Out_JogFwd) OR Out_JogRev)));

Out_Connected := Inp_Connected;
Out_Enabled := Inp_Enabled;
Out_Faulted := Inp_Faulted;
Out_DiagnosticAvailable := Inp_DiagnosticAvailable;
Out_ReconfigureBusy := Inp_ReconfigureBusy;
Out_ReconfigureDone := Inp_ReconfigureDone;
Out_ReconfigureFailed := Inp_ReconfigureFailed;
Out_RequestReconfigure := FALSE;
IF ((Inp_Inhibit OR Inp_Uninhibit) AND NOT (CommandLatch)) THEN
    IF (Inp_CanReconfigure AND NOT (Inp_ReconfigureBusy)) THEN
        Out_RequestedEnable := NOT (Inp_Inhibit);
        Out_RequestReconfigure := TRUE;
        Out_ReconfigureBlocked := FALSE;
    ELSE
        Out_ReconfigureBlocked := TRUE;
    END_IF;
END_IF;
IF Inp_ReconfigureDone THEN
    Out_ReconfigureBlocked := FALSE;
END_IF;
CommandLatch := (Inp_Inhibit OR Inp_Uninhibit);
